#include <vector>

class Solution {
public:
    int finalElement(std::vector<int>& nums) {
        int n = nums.size();
        if (n == 1) return nums[0];
        int idx = 0, step = 1, remaining = n;
        bool left = true;
        while (remaining > 1) {
            if (left || remaining % 2 == 1) idx += step;
            remaining /= 2;
            step *= 2;
            left = !left;
        }
        return nums[idx];
    }
};

